import csv
TS='108335ab-9ad0-5222-b9a5-88d998152c65'
SP='335c2ab2-c7e3-551f-8bdc-96b15c59e4a8'
def load(id):
    d={}
    with open(VALUES_CSV) as f:
        rd=csv.reader(f); next(rd)
        for t,ts,v in rd:
            if t==id:
                d[ts]=v
    return d
temp=load(TS); sp=load(SP)
def mean_dev(date):
    devs=[]
    for ts,v in temp.items():
        if not ts.startswith(date): continue
        h=int(ts[11:13])
        if 8<=h<=18 and (sp.get(ts) not in (None,'')):
            devs.append(float(v)-float(sp[ts]))
    return sum(devs)/len(devs), len(devs)
a,n1=mean_dev('2018-04-13')
b,n2=mean_dev('2018-07-04')
print("2018-04-13 mean", a, "n", n1)
print("2018-07-04 mean", b, "n", n2)
print("difference (b-a)", b-a)
print("increase" if b>a else "decrease")
